:root {
    --layout-max-width: 1600px;
    --layout-news-columns: repeat(12, 1fr);
    --layout-card-gap: 1.5rem;
    --layout-card-direction: column;
    --layout-animation-style: recursive-depth-shift;
    --scaffold-line-color: rgba(var(--morph-accent-primary-rgb), 0.15);
}

#news-container {
    max-width: var(--layout-max-width);
    margin: 8rem auto;
    padding: 2rem;
    display: grid;
    grid-template-columns: var(--layout-news-columns);
    gap: var(--layout-card-gap);
    background-image: 
        linear-gradient(var(--scaffold-line-color) 1px, transparent 1px),
        linear-gradient(90deg, var(--scaffold-line-color) 1px, transparent 1px);
    background-size: calc(100% / 12) 50px;
    perspective: 1200px;
}

.news-card {
    position: relative;
    background: var(--morph-bg-secondary);
    border-left: 3px solid var(--morph-accent-primary);
    display: flex;
    flex-direction: var(--layout-card-direction);
    min-height: 300px;
    view-timeline: --card-view block;
    animation: reveal-scaffold both linear;
    animation-timeline: --card-view;
    animation-range: entry 10% exit 90%;
    overflow: hidden;
    transition: border-color 0.4s ease;
}

/* カードの不規則な配置パターン */
.news-card:nth-child(4n+1) { grid-column: span 7; aspect-ratio: 16/9; }
